
window.HAPA_WEAVE_GLSL="// Original teaching function for CJ; not extracted from the requested ISF URL.\n// p is a caller-declared 2D coordinate; phase is continuous, not TIME * live speed.\n// Returns a scalar pattern mask, NOT a signed-distance field.\nfloat hapaWeaveField(vec2 p, float phase, float warp, float lineWidth) {\n    vec2 q = p + warp * vec2(sin(p.y * 1.37 + phase * 0.70),\n                             sin(p.x * 1.13 - phase * 0.50));\n    float xThread = abs(sin(q.x * 3.14159265359 + 0.22 * sin(q.y + phase)));\n    float yThread = abs(sin(q.y * 3.14159265359 - 0.22 * sin(q.x - phase)));\n    float distanceToThread = min(xThread, yThread);\n    return 1.0 - smoothstep(lineWidth, lineWidth * 2.0 + 0.001, distanceToThread);\n}\n";
window.HAPA_WEAVE_ISF="/*{\n  \"ISFVSN\": \"2.0\",\n  \"VSN\": \"0.1.0\",\n  \"CREDIT\": \"Original Hapa teaching example prepared for CJ; not a third-party shader port.\",\n  \"DESCRIPTION\": \"One scalar weave field, useful as a generator or extracted material mask. Source colors are linear RGB; no tone mapping is applied. Not an SDF.\",\n  \"CATEGORIES\": [\n    \"Generator\",\n    \"Hapa Teaching\"\n  ],\n  \"INPUTS\": [\n    {\n      \"NAME\": \"patternScale\",\n      \"TYPE\": \"float\",\n      \"DEFAULT\": 6.0,\n      \"MIN\": 1.0,\n      \"MAX\": 12.0\n    },\n    {\n      \"NAME\": \"warp\",\n      \"TYPE\": \"float\",\n      \"DEFAULT\": 0.25,\n      \"MIN\": 0.0,\n      \"MAX\": 0.7\n    },\n    {\n      \"NAME\": \"lineWidth\",\n      \"TYPE\": \"float\",\n      \"DEFAULT\": 0.08,\n      \"MIN\": 0.02,\n      \"MAX\": 0.25\n    },\n    {\n      \"NAME\": \"useHostPhase\",\n      \"TYPE\": \"bool\",\n      \"DEFAULT\": true\n    },\n    {\n      \"NAME\": \"hostPhase\",\n      \"TYPE\": \"float\",\n      \"DEFAULT\": 0.0,\n      \"MIN\": -100000.0,\n      \"MAX\": 100000.0\n    },\n    {\n      \"NAME\": \"colorA\",\n      \"TYPE\": \"color\",\n      \"DEFAULT\": [\n        0.015,\n        0.035,\n        0.06,\n        1.0\n      ]\n    },\n    {\n      \"NAME\": \"colorB\",\n      \"TYPE\": \"color\",\n      \"DEFAULT\": [\n        0.05,\n        0.65,\n        0.4,\n        1.0\n      ]\n    },\n    {\n      \"NAME\": \"gain\",\n      \"TYPE\": \"float\",\n      \"DEFAULT\": 1.0,\n      \"MIN\": 0.0,\n      \"MAX\": 4.0\n    },\n    {\n      \"NAME\": \"maskOnly\",\n      \"TYPE\": \"bool\",\n      \"DEFAULT\": false\n    }\n  ]\n}*/\n\n// Original teaching function for CJ; not extracted from the requested ISF URL.\n// p is a caller-declared 2D coordinate; phase is continuous, not TIME * live speed.\n// Returns a scalar pattern mask, NOT a signed-distance field.\nfloat hapaWeaveField(vec2 p, float phase, float warp, float lineWidth) {\n    vec2 q = p + warp * vec2(sin(p.y * 1.37 + phase * 0.70),\n                             sin(p.x * 1.13 - phase * 0.50));\n    float xThread = abs(sin(q.x * 3.14159265359 + 0.22 * sin(q.y + phase)));\n    float yThread = abs(sin(q.y * 3.14159265359 - 0.22 * sin(q.x - phase)));\n    float distanceToThread = min(xThread, yThread);\n    return 1.0 - smoothstep(lineWidth, lineWidth * 2.0 + 0.001, distanceToThread);\n}\n\nvoid main() {\n    float aspect = RENDERSIZE.x / max(RENDERSIZE.y, 1.0);\n    vec2 p = (isf_FragNormCoord - 0.5) * vec2(aspect, 1.0) * patternScale;\n    float phase = useHostPhase ? hostPhase : TIME * 0.35;\n    float mask = hapaWeaveField(p, phase, warp, lineWidth);\n    vec3 linearColor = mix(colorA.rgb, colorB.rgb, mask) * gain;\n    gl_FragColor = vec4(maskOnly ? vec3(mask) : linearColor, 1.0);\n}\n";
window.HAPA_FINISH_ISF="/*{\"ISFVSN\":\"2.0\",\"VSN\":\"0.2.0\",\"CREDIT\":\"Original Hapa Zerbini showcase; not a third-party port.\",\"DESCRIPTION\":\"Display-referred brushed finishing filter. Apply AFTER tone mapping and sRGB conversion. Does not add another display transform.\",\"CATEGORIES\":[\"Filter\"],\"INPUTS\":[{\"NAME\":\"inputImage\",\"TYPE\":\"image\"},{\"NAME\":\"amount\",\"TYPE\":\"float\",\"DEFAULT\":0.16,\"MIN\":0,\"MAX\":0.65},{\"NAME\":\"enabled\",\"TYPE\":\"bool\",\"DEFAULT\":true}]}*/\nfloat hash21(vec2 p){return fract(sin(dot(p,vec2(127.1,311.7)))*43758.5453);}\nvoid main(){\n vec2 uv=isf_FragNormCoord,px=1./RENDERSIZE;\n vec3 c=IMG_NORM_PIXEL(inputImage,uv).rgb;\n if(enabled){\n  vec3 l=IMG_NORM_PIXEL(inputImage,uv-vec2(px.x,0)).rgb,r=IMG_NORM_PIXEL(inputImage,uv+vec2(px.x,0)).rgb;\n  vec3 t=IMG_NORM_PIXEL(inputImage,uv+vec2(0,px.y)).rgb,b=IMG_NORM_PIXEL(inputImage,uv-vec2(0,px.y)).rgb;\n  float edge=length(r-l)+length(t-b);\n  vec3 poster=floor(c*25.+.5)/25.;c=mix(c,poster,amount*.33);\n  c*=1.-min(.32,edge*.55)*amount;\n  // Stable screen grain avoids shimmer and does not depend on frame count.\n  float grain=hash21(floor(gl_FragCoord.xy)*vec2(.41,1.));c+=(grain-.5)*.020*amount;\n }\n gl_FragColor=vec4(clamp(c,0.,1.),1.);\n}\n";

